import {wadExp, wadMul, unsafeWadDiv} from "solmate/utils/SignedWadMath.sol";

function getPrice(
    int256 initialPrice,
    int256 decayConstant,
    int256 timeSinceStart
) public pure returns (int256) {
    // price = initialPrice * e^(-decayConstant * time)
    int256 exponent = unsafeWadDiv(-decayConstant * timeSinceStart, 1e18);
    return wadMul(initialPrice, wadExp(exponent));
}
